    // vector, so the two components are computed once per move rather than
    // once per element.
    const { items } = this.#view;
    const dx = -delta * this.#ux;
    const dy = -delta * this.#uy;

    for (let i = lo; i < hi; i += 1) {
      report(items[i]!, dx, dy, runtime.space);
