// VisualLiftSession
// ---------------------------------------------------------------------------

/**
 * One visual's active presentation mode. Composes the inline-style lease and,
 * where applicable, the top-layer lease. It exposes only the transform
 * composition downstream movement and landing need, and never updates geometry,
 * animates, or invokes callbacks.
 */
export type VisualLiftSession = Readonly<{
  visual: HTMLElement;
  /** The authored/lift base transform the drag translation is composed with. */
  baseTransform: string;
  /**
   * The full transform string for a viewport delta.
   *
   * **Allocation-free in every mode.** The two lifted modes translate the
   * viewport delta directly; the in-place mode projects it through the inverse
   * of its inherited box space, which is four multiplies over scalars the
   * session captured at acquisition. Nothing on this path allocates except the
   * transform string itself.
   */
  compose(x: number, y: number): string;
  /**
   * **The delta `write` last composed and assigned** — where the visual *is*,
   * in the origin-relative viewport space `compose` and `write` consume.
   * `(0, 0)` until the first `write`, which is the truth for an operation that
   * never rendered and for a pointerless one.
   *
   * **The landing tail opens from here rather than from the pointer**: a
   * behavior that constrains, clamps, snaps or externally drives its visual
   * writes something other than the raw pointer delta, and a pointerless
   * operation has no pointer at all, so the pointer form would interpolate from
   * a position the visual has never been at.
   *
   * **Kernel-read.** The behavior is handed a {@link BehaviorLiftSession},
   * which does not carry this member.
   *
   * `compose` records nothing: composing is not rendering.
   */
  rendered: Point;
  /**
   * Composes a viewport delta and writes it to the visual's inline transform.
   *
   * **The behavior is the only caller.** The kernel writes nothing at the join:
   * the visual reaches its decided position by being released into flow, and
   * whatever interpolation follows the drop happens on the released element,
   * through a property this session never writes.
   *
   * A throw here is classified `FAILURE_RENDERER_WRITE` by the caller, which is
   * a semantic classification for a load-bearing write — a visual that stops
   * tracking the pointer is a fault the user sees, and the drop lands where the
   * visual is.
   */
  write(x: number, y: number): void;
  dispose: Disposer;
}>;

/**
 * What a **behavior** is handed: the same physical session, positively
 * projected to the four members it may use.
 *
 * `rendered` and `dispose` are kernel-only. The session's lifetime is the
 * kernel's: disposing it from `activation.effect` or `moved` would drop the
 * inline-style lease — and, in a lifted mode, the top-layer lease — while the
 * recorded delta still describes the last `write`, so the tail would start
 * from a visual that is no longer lifted.
 *
 * The projection is type-level. The kernel passes the *same object* under the
 * narrower type, so it costs no allocation.
 *
 * **It does not project away the timing.** `write` stays callable and stays
 * *effective* — no phase test, no operation check — so calling it after the
 * kernel has sampled the delta the drop travels from moves a visual the
 * settlement has already read, and calling it after retirement writes onto an
 * element no live operation owns. Both are outside the contract and neither is
 * refused.
 */
export type BehaviorLiftSession = Readonly<
  Pick<VisualLiftSession, 'visual' | 'baseTransform' | 'compose' | 'write'>
>;

/**
 * The inverse of an inherited linear part, or `null` for the identity, a
 * singular space or a non-finite one.
 *
 * `null` means **the local delta is the viewport delta** — the correct answer
 * for an untransformed ancestry and the honest one for a space that cannot be
 * inverted. It is also what lets `compose` skip the projection entirely on the
 * hot path.
 *
 * **The shape says nothing about which element's ancestry it describes**, and
 * three values of it are live at once: the space above the visual, the space
 * above the item, and the session's own projection — which is the space an
 * *in-place* translate acts in and is `null` for both lifted modes, because a
 * lifted visual is repositioned into the viewport. Each is named where it is
 * published; none of them is *the* inherited space.
 */
export type InheritedSpace = Readonly<{
  a: number;
  b: number;
  c: number;
  d: number;
}> | null;

function makeSession(
  visual: HTMLElement,
  baseTransform: string,
  projection: InheritedSpace,
  dispose: Disposer,
): VisualLiftSession {
  const suffix = baseTransform ? ` ${baseTransform}` : '';

  const compose = projection
    ? (x: number, y: number): string =>
        `translate(${projection.a * x + projection.c * y}px, ${
          projection.b * x + projection.d * y
        }px)${suffix}`
    : (x: number, y: number): string => `translate(${x}px, ${y}px)${suffix}`;

  // The recorded delta, mutable here and `Point` everywhere else. One object
  // per operation, written in place: recording costs these two field writes per
  // sample, where re-publishing a fresh `{ x, y }` would put an allocation on
  // the pointer-sample path, which is allocation-free.
  const rendered = { x: 0, y: 0 };

  return {
    visual,
    baseTransform,
    compose,
    rendered,
    write(x: number, y: number): void {
      // Recorded **after** the assignment, deliberately. A composition or style
      // write that throws is classified `FAILURE_RENDERER_WRITE` by the caller,
      // and the visual is then wherever it already was — so recording first
      // would leave the session claiming a delta the element never took, and
      // the drop would travel from a position that only the record believes.
      visual.style.transform = compose(x, y);
      rendered.x = x;
      rendered.y = y;
    },
    dispose,
  };
}

/**
 * The inverse of an inherited linear part, ready to turn a viewport delta into
 * the local translation that produces it, or `null` when that space is the
 * identity or is unusable.
 *
 * **Whose ancestry it is comes from the caller**, and the two are spent in
 * different places. Above the *visual*, it is the space an in-place translate
 * acts in, because an in-place lift *prepends* its translate to the visual's
 * authored transform, so the translate sits outside that transform and is
 * scaled only by what the visual inherits — inverting the visual's own space
 * would divide its scale out twice, and a `scale(2)` visual would move half as
 * far as asked. Above the *item*, it is what a behavior writing a translate on
 * a sibling of the dragged item needs, which is a different element and
 * therefore a different space whenever the two do not coincide.
 *
 * The basis comes from `ancestry`, which walks the flat tree rather than
 * `offsetParent` — which stops at a shadow boundary and is `null` for a
 * fixed-position visual — so every flat-tree, shadow-root and
 * `display: contents` rule stays in the package that owns them.
 */
function inheritedSpaceOf(above: Space): InheritedSpace {
  const a = above[SPACE_A]!;
  const b = above[SPACE_B]!;
  const c = above[SPACE_C]!;
  const d = above[SPACE_D]!;

  if (a === 1 && b === 0 && c === 0 && d === 1) {
    // The common case. A null projection makes `compose` skip the arithmetic
    // entirely on the hot path.
    return null;
  }

  const determinant = a * d - b * c;

  if (determinant === 0 || !Number.isFinite(determinant)) {
    return null;
  }

  return {
    a: d / determinant,
    b: -b / determinant,
    c: -c / determinant,
    d: a / determinant,
  };
}

/**
 * What one acquisition produces: the session, and the two pre-lift ancestry
 * facts read beside the measurement.
 *
 * **Separate products rather than members on the session**, and the reason is
 * lifetime: every member of `VisualLiftSession` describes the state acquisition
 * *created*, while both spaces describe the state it *destroyed*. Putting them
 * on the session would put pre-lift facts inside the post-lift write
 * capability, next to a same-shaped projection holding a third value. The
 * kernel copies them onto `ActivationScope`, where the other pre-lift facts —
 * `originRect`, `boxPre` — already live.
 *
 * **The two are the same object whenever the visual is the item**, which is the
 * common case, so nothing pays for a divergence it does not have.
 */
export type LiftAcquisition = Readonly<{
  session: VisualLiftSession;
  visualSpace: InheritedSpace;
  itemSpace: InheritedSpace;
}>;

/**
 * Acquires a lift.
 *
 * Everything geometric is read **here, before anything is mutated**: the two
 * ancestries, then the visual's box measured through the first of them. The
 * composed element→viewport matrix (the faithful mode's base transform), the
 * untransformed border-box size (both lifted modes' fixed box), the inherited
 * zoom (which the top layer does not escape, so a lifted visual divides it back
 * out), the inverse used by the in-place projection, and the two spaces the
 * activation scope publishes all come from this one sequence.
 *
 * **That the reads are all taken here is load-bearing rather than merely
 * efficient.** Everything below them mutates the visual — positioning,
 * dimensions, top-layer state, transforms — so a traversal taken afterwards
 * reads a different ancestry, and box-quad's own contract says two walks may
 * legitimately disagree. A behavior that measured for itself could therefore
 * lift on one coordinate snapshot and report consumer deltas from another.
 *
 * **The item's ancestry is a second walk, and it is spent deliberately.** No
 * layout is read for it and no rect is measured; it is computed style up the
 * flat tree, once per activation, and only when the item is not the visual. The
 * alternative — one walk publishing both — needs a designated boundary element
 * inside the measurement, which is a concept this library would then have to
 * carry for a consumer that knows both elements before it calls.
 *
 * Throws when either space cannot be read, or the visual has no single box — a
 * disconnected or fragmented visual, or a 3D transform this library does not
 * model. The caller classifies it as `FAILURE_ACTIVATION`; silently flattening
 * 3D to its 2D projection would produce a wrong lift rather than a refused one.
 *
 * Style capture and top-layer acquisition are composed into the returned
 * `dispose` in reverse acquisition order.
 */
export function acquireLift(
  visual: HTMLElement,
  item: HTMLElement,
  mode: LiftMode,
  originRect: DOMRectReadOnly,
  realm: DOMRealm,
  unwind: Unwind,
): LiftAcquisition {
  const above = space();
  // One buffer when the two coincide, which is both the common case and the
  // whole of the identity guarantee: the two published spaces are then the
  // same value, not two values that happen to agree.
  const itemAbove = item === visual ? above : space();
  const measured = box();

  if (
    !ancestry(visual, above) ||
    (itemAbove !== above && !ancestry(item, itemAbove)) ||
    // The visual is measured **through** the ancestry just read, so the
    // matrix and the space it is decomposed against are one observation.
    !coordinates(visual, measured, above)
  ) {
    // No readable space: the visual is disconnected, fragmented across lines,
    // or something on either chain is not representable in 2D.
    throw new Error('drag: presentation/visual-no-box-space');
  }

  // **Read before anything mutates, published for every mode.** The in-place
  // branch below hands the visual's space to `compose`; the lifted branches
  // hand `compose` the identity, because a lifted visual is repositioned into
  // the viewport, and still publish both of these.
  const visualSpace = inheritedSpaceOf(above);
  const itemSpace =
    itemAbove === above ? visualSpace : inheritedSpaceOf(itemAbove);
  const width = measured[BOX_WIDTH]!;
  const height = measured[BOX_HEIGHT]!;
  const ancestorZoom = above[SPACE_ANCESTOR_ZOOM]!;
  const style = realm.window.getComputedStyle(visual);
  const styleLeaseDisposer = captureInlineStyles(visual);

  // Everything below mutates the visual. The style lease is already held, but
  // the *caller* only learns about it through the returned session — so a throw
  // from here on would leave the visual promoted and restyled with nothing that
  // could ever restore it. Acquisition is all-or-nothing.
  try {
    if (mode === LIFT_IN_PLACE) {
      // Stay in the container, ride the authored transform, and suppress
      // transitions so engine transform writes apply instantly.
      const own = style.transform;
      visual.style.transition = 'none';

      return {
        session: makeSession(
          visual,
          own === 'none' ? '' : own,
          visualSpace,
          styleLeaseDisposer,
        ),
        visualSpace,
        itemSpace,
      };
    }

    neutralizeUA(visual, style);
    visual.style.transition = 'none';
    visual.style.position = 'fixed';
    visual.style.inset = 'auto';
    visual.style.width = `${width}px`;
    visual.style.height = `${height}px`;

    let base = '';

    if (mode === LIFT_FAITHFUL) {
      const a = measured[BOX_A]!;
      const b = measured[BOX_B]!;
      const c = measured[BOX_C]!;
      const d = measured[BOX_D]!;

      base = `matrix(${a}, ${b}, ${c}, ${d}, ${measured[BOX_E]!}, ${measured[BOX_F]!})`;
      // Net zoom 1: the matrix is the sole source of scale.
      visual.style.zoom = `${1 / ancestorZoom}`;
      visual.style.top = '0';
      visual.style.left = '0';
      visual.style.transformOrigin = '0 0';
      // **Written now, not left to the first `moved()`.** A faithful lift puts
      // the visual at the viewport origin and encodes its entire position in
      // the matrix, so until something writes a transform the row paints in the
      // top-left corner at its untransformed size. The kernel activates *on* a
      // pointer sample and renders only from the next one, so that window is a
      // real frame whenever the pointer pauses or its samples coalesce.
      // Promotion has to be visually transparent on its own — the same reason
      // `neutralizeUA` re-asserts the authored UA properties. The flat branch
      // below needs no equivalent: it positions from `originRect` and its base
      // transform is empty.
      visual.style.transform = base;
    } else {
      if (ancestorZoom !== 1) {
        visual.style.zoom = `${1 / ancestorZoom}`;
      }

      visual.style.top = `${originRect.top + originRect.height / 2 - height / 2}px`;
      visual.style.left = `${originRect.left + originRect.width / 2 - width / 2}px`;
    }

    const topLayerDisposer = acquireTopLayer(visual, unwind);

    const session = makeSession(visual, base, null, () => {
      // `finally`, not sequence: restoring the inline styles is the one
      // guarantee this module owns outright, and a `hidePopover()` that throws
      // — or a prior-popover restoration that does — must not cost the visual
      // its authored `position`, `width` and `transform` permanently.
      try {
        topLayerDisposer();
      } finally {
        styleLeaseDisposer();
      }
    });

    return { session, visualSpace, itemSpace };
  } catch (error) {
    styleLeaseDisposer();
    throw error;
  }
}
/**
 * One controller's owning DOM environment, derived from an element's
 * `ownerDocument` and its `defaultView`. Document listeners, scroll offsets,
 * animation frames, DOM constructors, and realm-sensitive type checks use this
 * value rather than ambient globals, so a controller created inside an iframe
 * behaves correctly.
 *
 * Construction fails explicitly when `defaultView` is `null`; falling back to
 * the ambient `window` would mix realms.
 *
 * The construction-time context carries it — `BehaviorContext` at the kernel
 * tier, the feature context at the middle tier — so a behavior schedules and
 * measures in the realm the controller was built on rather than in the ambient
 * one.
 */
export type DOMRealm = Readonly<{
  document: Document;
  window: Window & typeof globalThis;
  /** Structural check for an element belonging to this or any realm. */
  isElement(value: unknown): value is HTMLElement;
}>;

export function createRealm(element: Element): DOMRealm {
  const document = element.ownerDocument;
  const view = document.defaultView;

  if (!view) {
    throw new Error('drag: realm/no-owning-window');
  }

  return {
    document,
    window: view,
    isElement(value): value is HTMLElement {
      // This realm first. `instanceof` is exact where a bare `nodeType === 1`
      // test is not: that test accepts SVG and MathML elements, and any plain
      // object carrying the property, all of which the `HTMLElement` return
      // type claims they are not.
      if (value instanceof view.HTMLElement) {
        return true;
      }

      // Another realm's element is not `instanceof` *this* realm's constructor,
      // so reach that realm's constructor through the node's own document
      // rather than weakening the check to a duck-type.
      const foreign = (value as Node | null | undefined)?.ownerDocument
        ?.defaultView;

      return foreign != null && value instanceof foreign.HTMLElement;
    },
  };
}
/**
 * The transactional seam driver.
 *
 * Every substantial action has three steps — **prepare** (validation, pure
 * calculation, DOM reads, local acquisition), **commit** (short, effectively
 * non-throwing), **post-commit effects** (DOM writes, lifetime closes,
 * continuations, callbacks). The order is the shape of the contract rather than
 * a rule the behavior obeys: the kernel drives all three steps and the behavior
 * supplies two pure-ish callbacks.
 *
 * `SeamDriver.runTransition` runs those steps. The discard policy and the
 * failure policy differ per seam, so each caller applies its own to the outcome.
 */
import { DraggableWarning, type Notify } from './errors.ts';
import type { FailureStage } from './failures.ts';
import type { Draft, Frame } from './frames.ts';
import type { Phase } from './phases.ts';
import type { FrameTransaction } from './transaction.ts';

/**
 * A seam that stages nothing uses `Prepared = true` and returns the literal.
 *
 * `extends {}` excludes `null` and `undefined` while still admitting the `true`
 * sentinel, an element, or any object — which keeps `Prepared | null`
 * unambiguous as the discard signal without leaving it to prose.
 */
export type Transition<
  Part extends object,
  Prepared extends {} = true,
  Capability = void,
> = Readonly<{
  /**
   * Returns the staged value, or `null` to discard. Must not touch `current`,
   * must not perform DOM writes, and must keep every acquisition local —
   * everything it acquires travels out through `Prepared`.
   */
  prepare(draft: Draft<Part>, capability: Capability): Prepared | null;

  /**
   * Post-commit effects, for an already-published transition. A throw here
   * becomes a classified failure **from the committed state**; the transition
   * is not reverted.
   */
  effect(
    current: Readonly<Frame<Part>>,
    prepared: Prepared,
    capability: Capability,
  ): void;
}>;

/**
 * Behavior action tags get the same envelope, which is what makes "the behavior
 * never calls `begin()`/`commit()`" hold for behavior-initiated work too.
 *
 * `Prepared` is opaque to the kernel, which threads it; the behavior narrows it
 * by tag.
 */
export type ActionTransition<Part extends object> = Readonly<{
  prepare(tag: number, argument: unknown, draft: Draft<Part>): {} | null;
  effect(
    tag: number,
    argument: unknown,
    current: Readonly<Frame<Part>>,
    prepared: {},
  ): void;
}>;

/** `prepare` returned `null` — nothing happened. */
export const SEAM_DISCARDED = 0;
/** Classified; nothing committed. */
export const SEAM_PREPARE_FAILED = 1;
/** Committed, effect returned normally. */
export const SEAM_COMMITTED = 2;
/** Classified, from the committed state. */
export const SEAM_EFFECT_FAILED = 3;

/**
 * What one seam run did, named once so every caller branches on the same
 * vocabulary.
 *
 * There are no predicate helpers over this union; call sites name the outcomes
 * they mean.
 *
 * **A classified failure must also stop incompatible continuation**, and the
 * driver is where that is enforced, because the failure checkpoint is *queued*.
 * Between the throw and the checkpoint there is a window in which the driver
 * would otherwise still be doing success work — so `SEAM_PREPARE_FAILED`
 * returns before `commit()`, and `SEAM_EFFECT_FAILED` returns before anything
 * is staged.
 */
export type SeamOutcome =
  | typeof SEAM_DISCARDED
  | typeof SEAM_PREPARE_FAILED
  | typeof SEAM_COMMITTED
  | typeof SEAM_EFFECT_FAILED;

/**
 * No phase is open. `FailureStage` starts at 1, so `0` and `-1` are free to
 * carry the two readings a stage alone cannot.
 */
const NO_STAGE = 0;

/**
 * The stage of a phase whose failures are **reported, never classified**.
 *
 * One sentinel, because there is one report channel.
 *
 * The landing measurement opens under it. It runs when the operation is
 * already **committed**, so classifying there would settle a drop
 * that really happened. Applying the sentinel to the whole phase is what makes
 * an explicit `kernel.fail` inside it behave exactly like a throw inside it.
 */
const UNCLASSIFIED = -1;

/** What an open phase classifies against. */
type PhaseStage = FailureStage | typeof UNCLASSIFIED;

/**
 * A phase that threw or latched a failure, as a value.
 *
 * A private symbol, so it is distinguishable from every legal `Prepared`,
 * `null` and callback value without constraining what a seam may stage.
 */
const FAILED = Symbol();

/**
 * **The phase machine behind one controller's seams.**
 *
 * It enforces _exactly one phase open at a time_ across calls, which is an
 * invariant over the whole object rather than a property of any field: the open
 * stage, the latched failure, the unclassified reason, the staged value and the
 * re-entry latch are one state, reset together as each phase opens.
 *
 * **Every field is private and nothing outside reads or writes one.** What
 * crosses the boundary is the run operations, the staged-value consumer,
 * `requestFailure` and the diagnostic predicate `isInSeam`.
 */
export class SeamDriver<Part extends object> {
  /** The pair every transactional seam publishes and reads. */
  readonly #frames: FrameTransaction<Part>;

  /** Queues a classified failure against the operation the kernel holds. */
  readonly #fail: (stage: FailureStage, error: unknown) => void;

  /**
   * The armed controller's route to the spec's `reportError`, which applies the
   * kernel's one diagnostic refusal. No checkpoint is queued, no recovery is
   * selected, and the operation's own outcome is untouched — which is what
   * makes everything the driver sends here a {@link DraggableWarning}.
   */
  readonly #notify: Notify;

  /**
   * The stage the open phase classifies against, or `NO_STAGE` between phases.
   * One field rather than a set of booleans: *whether* behavior code is
   * running, *which* operation stage owns its failures, and *whether* they are
   * classified at all are three readings of the same fact, and splitting them
   * lets them drift apart.
   */
  #openStage: PhaseStage | typeof NO_STAGE = NO_STAGE;

  /**
   * Set by `requestFailure`, cleared as each phase opens. **A latched failure
   * is indistinguishable from a throw at the driver boundary** — which is the
   * whole point: enqueuing a checkpoint is not enough on its own, because the
   * checkpoint is queued and the window before it applies is exactly what the
   * latch closes.
   */
  #failureRequested = false;

  /**
   * The message an `UNCLASSIFIED` phase reports under. Set as that phase opens
   * and read only while it is open, which is the same lifetime
   * `#failureRequested` has and for the same reason: the driver runs exactly
   * one phase at a time.
   *
   * A string rather than a `FailureStage`: the warning names its reason in its
   * message, so the driver carries the reason rather than a classification it
   * is about to refuse to apply.
   */
  #unclassifiedReason = '';

  /**
   * The staged value of the last committed transition. Owned here rather than
   * passed in, so no call path can skip the reset: passed in, a `runTransition`
   * handed no slot would leave the previous seam's value readable.
   */
  #staged: unknown = null;

  /**
   * Set when a seam is re-entered, and the reason the refusal is a latch rather
   * than a bare `throw`: the nested call raises from inside the outer seam's
   * `prepare` or `effect`, so the outer `catch` would otherwise classify an
   * invariant break as an ordinary behavior failure and swallow it.
   *
   * **This, and not what was thrown, is the whole decision** — which is what
   * makes it a latch rather than an error code. The driver never consults the
   * raised value, so behavior code that catches the refusal has caught nothing
   * it can act on and unwinds exactly as one that let it pass.
   */
  #reentry = false;

  /**
   * All of them are controller-invariant and held for its life, so no seam
   * allocates to reach one.
   */
  constructor(
    frames: FrameTransaction<Part>,
    fail: (stage: FailureStage, error: unknown) => void,
    notify: Notify,
  ) {
    this.#frames = frames;
    this.#fail = fail;
    this.#notify = notify;
  }

  /**
   * Runs one frame transaction: begin → prepare → commit → effect. Returns the
   * outcome; the caller applies its own seam's continuation policy.
   *
   * A successful preparation commits. Nothing between `prepare` and the
   * commit reads a request: a cancel or destroy raised inside the seam is
   * registered and applied at a unit boundary, after this one, so it cannot
   * invalidate the preparation the running unit computed.
   *
   * A committed transition leaves its `Prepared` value in the staging slot. The
   * kernel reads one such value after the seam returns: the release seam's
   * `ResolutionCommand`. Read it with {@link SeamDriver.consumeStaged}.
   *
   * `effectStage` is the stage of a throw from `effect`. A behavior action needs
   * it: it resolves an insertion in `prepare` and moves the placeholder in
   * `effect`, and a throw in each is classified at its own stage. An explicit
   * `kernel.fail` can name a narrower stage.
   */
  runTransition<Prepared extends {}, Capability>(
    transition: Transition<Part, Prepared, Capability>,
    capability: Capability,
    stage: FailureStage,
    phase: Phase | null = null,
    effectStage: FailureStage = stage,
  ): SeamOutcome {
    // `#callAndHandleFailure` also refuses, but too late for this method: a
    // transaction mutates kernel state before its first phase opens, and
    // `begin()` would rebuild the draft the outer seam is still building.
    this.#refuseReentry();

    if (this.#staged !== null) {
      // The clear below makes this harmless, and the report makes it visible. A
      // staged value here means the previous seam neither consumed nor dropped
      // it, which is the one way a command can outlive its transaction.
      this.#notify(new DraggableWarning('drag: seam/staged-unconsumed'));
    }

    this.#staged = null;
    this.#frames.begin();

    const prepared = this.#callAndHandleFailure(stage, () =>
      transition.prepare(this.#frames.draft, capability),
    );

    if (prepared === FAILED) {
      return SEAM_PREPARE_FAILED;
    }

    if (prepared === null) {
      return SEAM_DISCARDED; // the draft is abandoned
    }

    this.#frames.commit(phase);

    const effected = this.#callAndHandleFailure(effectStage, () =>
      transition.effect(this.#frames.current, prepared, capability),
    );

    if (effected === FAILED) {
      return SEAM_EFFECT_FAILED;
    }

    // Stage after the effect, so anything the effect triggers, such as a queued
    // action or a consumer callback, cannot observe or clear this value.
    //
    // Unconditional: a request the effect raised is applied after this unit.
    // The release seam's caller queues the round-trip as its own unit. That
    // unit's entry declines on a registered cancel, and applying a destroy at
    // this unit's boundary discards the unit.
    this.#staged = prepared;
    return SEAM_COMMITTED;
