 *
 * The assembler produces a `SortableSlots` and the behavior takes one as an
 * argument. Nothing here knows what a feature is: by the time the behavior
 * runs, the contribution objects are gone and only these fields and their
 * closures exist.
 *
 * The shape is deliberately flat — `slots.resolveInsertion(...)` is one
 * property read and one call. The assembler flattens every member of
 * `InsertionGeometry` — `resolve`, `invalidate`, `moved`, and `retire` into the
 * unwind list — so the pairing is a construction-time claim rather than a
 * hot-path indirection.
 */
import type { DraggableError, DraggableWarning } from '../kernel/errors.ts';
import type { Disposer } from '../kernel/lifetimes.ts';
import type { InheritedSpace } from '../kernel/presentation.ts';
import type { LandingTiming } from '../shared/composition.ts';
import type { ItemSource, SortableOnEnd } from './config.ts';
import type { CollectionSnapshot, Insertion, OnReorder } from './domain.ts';
import type { PlaceholderFactory } from './placement.ts';
import type { DisplacementSettle } from './rect-index.ts';

/**
 * **One element a committed move displaced, and the vector it travelled,
 * negated.**
 *
 * Passed *into* the axis rather than returned from it, so a composition with no
 * displacement sink constructs nothing on a committed move: the axis takes
 * `null` and never enters the walk. The vector is negated because that is what
 * an inverse-FLIP contribution starts from — the element jumped by `+v`, so a
 * contribution of `-v` decaying to zero shows it travelling.
 *
 * **`space` is the units the vector is in, so a report states its own.** The
 * vector is a viewport quantity and a `translate` is not, so a sink writing one
 * has to project; `space` is the inverse of the linear part the collection
 * inherits, or `null` when that is the identity and the two coincide. It rides
 * with the vector rather than being read once and held, so there is no interval
 * over which it must stay valid and nothing for the sink to invalidate.
 */
export type DisplacementReport = (
  element: HTMLElement,
  dx: number,
  dy: number,
  space: InheritedSpace,
) => void;

/**
 * The fields an axis rule may read off the frame. **The behavior passes
 * whichever frame its seam was handed** — a draft inside a `prepare`, a
 * readonly frame inside an `effect` — and structural typing does the rest, so
 * no view is ever materialized.
 *
 * **This is the widest view, not the required one.** A feature declares its own
 * narrower view in its own module and the behavior's frame satisfies both:
 * `y()` names `pointerY` and `item`, `xy()` names `pointerX` as well. The type
 * here is the ceiling the behavior guarantees to supply.
 */
export type InsertionFrameView = Readonly<{
  insertion: Insertion | null;
  /**
   * **The collection the gap indexes into**, or `null` before a lift.
   *
   * It is the frame's own committed snapshot: a value a gap may be resolved
   * and version-stamped against, and one that does not move underneath a rule
   * holding it.
   */
  snapshot: CollectionSnapshot | null;
  /** Read by the two-dimensional rule; `y()` ignores it. */
  pointerX: number;
  pointerY: number;
  /**
   * The dragged item, or `null` before a lift. The destination view is the
   * collection minus this item, and an axis rule that cannot exclude it
   * measures a lifted element whose centre tracks the pointer — so it would win
   * every search and pin the gap to its own slot.
   *
   * It is read off the frame rather than off {@link InsertionRuntimeView}: the
   * item is already committed frame state, and duplicating it onto the
   * per-operation view would create a second copy that could drift.
   */
  item: HTMLElement | null;
}>;

/**
 * Non-frame state travels as a **second argument**, because frame state and
 * runtime state have separate owners and separate lifetimes. It is one small
 * per-operation object — the reason it is per-operation rather than
 * per-controller is `placeholder`, which cannot be non-null before activation.
 */
export type InsertionRuntimeView = Readonly<{
  placeholder: HTMLElement;
  /**
   * The installed `box` resolver, or `null` when the config names neither `box`
   * nor `visual`.
   *
   * **The axis rule measures candidate boxes, not candidate visuals.** The
   * incumbent every candidate is compared against is the placeholder, and the
   * placeholder occupies the **box's** removed footprint, so both sides of the
   * comparison are the same kind of rect. Measuring candidates as visuals
   * instead measures the incumbent one way and its challengers another, which
   * is a hysteresis defect rather than a rounding one.
   *
   * Under the default `box === visual` the two coincide, so the common case is
   * untouched.
   *
   * Nullable rather than normalized to identity, because the minimal
   * composition names neither slot and would otherwise pay an identity call per
   * candidate per rebuild.
   */
  box: ((item: HTMLElement) => HTMLElement) | null;
  /**
   * **The installed displacement sink's settle walk**, or `null` when no
   * displacement feature is composed.
   *
   * An axis hands it the buffer a rebuild has just measured and gets *settled*
   * geometry back, rather than where an animation currently draws each row. It
   * reads no layout, so a rebuild that runs mid-flight costs one call and
   * nothing per candidate — and no contribution ever has to be released so that
   * something can measure.
   */
  settle: DisplacementSettle | null;
  /**
   * **The inverse of the linear part the collection inherits**, or `null` for
   * an untransformed ancestry — the projection that turns a viewport
   * displacement into the `translate` a sink writes.
   *
   * Passed straight on to {@link DisplacementReport}; the axis owns the vector
   * and never the units. It is a fact about the ancestry at grab, captured once
   * at activation from the measurement the lift already took.
   */
  space: InheritedSpace;
}>;

export type SortableSlots = Readonly<{
  /* required, filled by the axis feature */
  resolveInsertion(
    frame: InsertionFrameView,
    runtime: InsertionRuntimeView,
  ): Insertion | null;
  /**
   * The behavior's only way to say "the geometry you cached is stale". **Lazy
   * by contract**: scroll and resize call it many times a second, so it may not
   * read geometry.
   */
  invalidateInsertion(): void;
  /**
   * **The committed move has landed**: leave the cache describing the tree, and
   * tell `report` what moved. Required — an axis that reports nothing still has
   * to answer for its own cache.
   */
  movedInsertion(
    frame: InsertionFrameView,
    runtime: InsertionRuntimeView,
    report: DisplacementReport | null,
  ): void;

  /* required */
  /**
   * **The collection as a pull source.** Called by `action.prepare(COLLECTION)`
   * on every `controller.invalidate()`, and once at construction for the
   * initial snapshot — never memoized, because the whole point is that the
   * library re-reads it.
   */
  items: ItemSource;
  onReorder: OnReorder;
  /**
   * Normalized to a shared no-op, so the call site needs no null check. It
   * takes an argument the behavior already has.
   */
  onStart(item: HTMLElement): void;

  /* optional; `null` when no feature filled them */
  placeholder: PlaceholderFactory | null;
  handle: ((item: HTMLElement) => HTMLElement | null) | null;
  /** The node faithfully lifted. Resolved once, at admission. */
  visual: ((item: HTMLElement) => HTMLElement) | null;
  /**
   * The geometry source. **Already defaulted to `visual` by the assembler**, so
   * this is `null` only when neither slot was written — which is what lets both
   * the admission path and the candidate loop skip the call entirely rather
   * than pay an identity per item.
   */
  box: ((item: HTMLElement) => HTMLElement) | null;
  /**
   * The tail's timing, or `null` when no landing is installed — in which case
   * the visual simply stays where the drop put it.
   */
  landingTiming: LandingTiming | null;
  /**
   * These stay nullable rather than normalized: their arguments are result
   * objects that would otherwise be constructed only to be discarded.
   */
  onEnd: SortableOnEnd | null;
  onError: ((error: DraggableError | DraggableWarning) => void) | null;

  /**
   * The displacement sink's visitor, or `null` when no displacement feature is
   * composed — which is the argument the axis is handed and the whole of what
   * a non-animating composition pays.
   */
  report: DisplacementReport | null;
  /**
   * The sink's settle walk, or `null` when nothing displaces. Copied onto the
   * per-operation view so an axis reads one field rather than reaching the slot
   * record.
   */
  settle: DisplacementSettle | null;
  /** Installation order; every reader walks it backwards. */
  retireHooks: readonly Disposer[];

  threshold: number;
}>;

/** The shared normalization target for an uninstalled `onStart`. */
export const NOOP_START = (): void => {};

export const DEFAULT_THRESHOLD = 8;
/**
 * Construction-time assembly: a merged config in, one `SortableSlots` in flat
 * form out.
 *
 * **The contribution objects are dropped.** After `assemble()` returns, the
 * only things that exist are the slot fields and the closures they hold — the
 * contribution objects and every reference to them are garbage. That is what
 * makes each feature's private state unreachable from the behavior, the kernel,
 * or a sibling feature.
 *
 * **No single-writer arbitration.** Each unique slot is produced by one config
 * key and read from that key's contribution directly, so there is no
 * accumulator to collide, no label to name in a diagnostic and no
 * `duplicate-contribution` identity. The keys are visited in schema order.
 */
import type { Disposer } from '../kernel/lifetimes.ts';
import type { LandingTiming } from '../shared/composition.ts';
import type { SortableConfig } from './config.ts';
import type { FeatureContext, SortableFeatureContext } from './feature.ts';
import type { DisplacementSettle } from './rect-index.ts';
import {
  DEFAULT_THRESHOLD,
  type DisplacementReport,
  NOOP_START,
  type SortableSlots,
} from './slots.ts';

export function assemble(
  config: SortableConfig,
  context: FeatureContext,
): SortableSlots {
  let landingTiming: LandingTiming | null = null;
  let report: DisplacementReport | null = null;
  let settle: DisplacementSettle | null = null;
  const retireHooks: Disposer[] = [];

  // **There are no required-slot checks.** The required first argument is what
  // guarantees the slots: `items`, `onReorder` and `axis` are compile errors
  // when absent, so runtime bytes restating that would buy nothing.
  //
  // **What a JS consumer meets instead is per slot, and only one of the three
  // is classified.** `onReorder` is the only one reached inside a seam, so it
  // is the only one that becomes a library failure — `FAILURE_RESOLUTION`.
  // `axis` fails below — at the key's own call when it is absent, and at the
  // flat slot record's dereference when it is a function that returns no
  // geometry — and `items` fails earlier still, at the construction-time pull
  // in `behavior.ts`: all three are the consumer's own native `TypeError` out
  // of their own `sortable()` call, with no stage, no `DraggableError` and no
  // `onError`. Only a later throw from a **valid** `items` — one that is a
  // function and raises during an `invalidate()` — reaches
  // `FAILURE_ACTION_PREPARE`.
  //
  // The library is the only producer of a context, so it is the only place the
  // brand is stamped. `as` emits nothing: every call below is
  // `install(context)`.
  const branded = context as SortableFeatureContext;

  try {
    // **Installation order is schema order**, written out rather than driven by
    // a loop over a heterogeneous array: the named capability keys, in the
    // order the schema declares them, and every reader of `retireHooks` walks
    // it backwards. With no unbounded position there is no fragment order to
    // preserve anywhere.
    const axis = config.axis(branded);

    // Cleanup is recorded **first**, before anything below can throw, and in
    // installation order: the axis feature's hook is first in installation
    // order and therefore *last* after the reverse, which is the documented
    // order for `[y(), …]`.
    //
    // Guarded, though the type declares `insertion` required: a JS-authored
    // installer that returns none must not fail *here*, where the unwind has
    // nothing recorded yet and the plugins have not run. It fails at the
    // record's dereference below, inside the same bracket, with everything that
    // installed already retired.
    if (axis.insertion) {
      retireHooks.push(axis.insertion.retire);
    }

    if (axis.retire) {
      retireHooks.push(axis.retire);
    }

    if (config.landing) {
      const landing = config.landing(branded);

      if (landing.retire) {
        retireHooks.push(landing.retire);
      }

      ({ landingTiming } = landing);
    }

    if (config.displacement) {
      const displacement = config.displacement(branded);

      if (displacement.retire) {
        retireHooks.push(displacement.retire);
      }

      ({ report, settle } = displacement);
    }

    // **The flat slot record is built inside the unwind bracket, and that
    // placement is normative.** There is no explicit
    // `the axis installer contributed no insertion geometry` throw:
    // `AxisContribution` declares `insertion` required, so a plugin-shaped
    // installer is not assignable, and a JS-authored violator is still
    // diagnosed — dereferencing a missing resolver throws by itself. An
    // explicit check would supply a better message, not the failure.
    //
    // **Where the dereference happens is the part that matters.** Building the
    // record after the bracket would trade a diagnostic string for a leak: the
    // throw would escape with every installer that already ran still holding
    // its private state. Asserting only that it throws passes against that
    // defect, so the test asserts the retirement too.
    const slots: SortableSlots = {
      // The dereference that stands in for a check. `insertion` is present for
      // every installer the type admits; the assertion is what makes a
      // JS-authored violator throw *here*, inside the bracket.
      resolveInsertion: axis.insertion.resolve,
      invalidateInsertion: axis.insertion.invalidate,
      movedInsertion: axis.insertion.moved,

      // **Not validated as a function.** The type says `ItemSource`; a JS
      // consumer that passes something else has already broken its own code at
      // the construction-time pull, before this record exists.
      items: config.items,
      onReorder: config.onReorder,
      // Two normalization rules, because "optional callback" is not one thing.
      // `onStart` becomes a shared module-level no-op, so its call site needs
      // no null check and allocates nothing; the terminal callbacks stay
      // nullable, because their arguments are result objects that would
      // otherwise be constructed only to be discarded.
      onStart: config.onStart ?? NOOP_START,
      onEnd: config.onEnd ?? null,
      onError: config.onError ?? null,
      // **Not domain-checked, but defaulted.** A `NaN` threshold makes the
      // travel test permanently false, so the drag never activates and **no
      // operation starts** — the consumer's own drag is broken and no library
      // invariant moves. The **default** is applied here, on this line, and not
      // by the merge: `mergeFragments` applies no defaults at all, because its
      // output is still the schema type while normalization is what produces
      // the flat record.
      threshold: config.threshold ?? DEFAULT_THRESHOLD,

      // **The consumer's factory or the library's own `<div>`.** There is no
      // contributed placeholder to lose a precedence question to, and no
      // adapter closure: the slot's type is the consumer's own
      // `PlaceholderFactory`, so what is stored here is the function the
      // consumer wrote.
      placeholder: config.placeholder ?? null,
      handle: config.handle ?? null,
      visual: config.visual ?? null,
      // **`box(item) = visual(item)` by default**, applied here so no
      // downstream reader has to know the rule. Falling through to `null` when
      // neither is written keeps the minimal composition free of an identity
      // call per candidate per rebuild.
      box: config.box ?? config.visual ?? null,
      landingTiming,

      report,
      settle,
      retireHooks,
    };

    // **Stored in installation order and walked backwards by every reader.**
    // The published guarantee is about execution order; a `reverse()` here
    // would be a second representation of it, with a mutation between the two.
    return slots;
  } catch (error) {
    // A later installer or the resolver dereference must not leak an earlier
    // feature's state. Factories are externally inert, so this is a retention
    // and diagnostics concern rather than a DOM leak — but the unwind is stated
    // as total, so it is total.
    //
    // **Total across construction, not merely here.** The collection is pulled
    // and copied ahead of the first installer rather than after this function
    // returns; were it pulled after, a throwing `items()` would leave every
    // hook below unrun and that sentence would be false of the call that drives
    // this one. That is why this needs no scope clause.
    for (let i = retireHooks.length - 1; i >= 0; i -= 1) {
      try {
        retireHooks[i]!();
      } catch (nested) {
        context.report(nested);
      }
    }

    throw error;
  }
}
// A fragment is a plain declarative partial config: every argument after `root`
// is an ordinary object literal carrying no brand, no `kind` tag and no
// provenance. **Every slot last-wins**, so the merge is one walk over the
// schema — there is no appending slot left since `plugins` was deleted with the
// bracket it existed for.
import type { Writable } from 'type-fest';
import type { DraggableError, DraggableWarning } from '../kernel/errors.ts';
import type { OnReorder, ReorderTransactionResult } from './domain.ts';
import type {
  AxisInstaller,
  SortableDisplacementInstaller,
  SortableLandingInstaller,
} from './feature.ts';

import type { PlaceholderFactory } from './placement.ts';

// Every callback slot is a named type alias, and that is normative rather than
// stylistic. Method shorthand is checked bivariantly even under `strict`, so a
// handler narrowed to a subset of a union's arms is silently accepted; and the
// inline property form does not survive this repo, because
// `@typescript-eslint/method-signature-style` is configured to `method` and
// `just lint-fix` rewrites it back into shorthand. A named alias is immune.
//
// `onStart`, `onEnd` and `onError` exist on both ordinary configs with
// different structures, so those three aliases are qualified by behavior.
// `ResolveHandle` and `ResolveElement` also collide but are structurally
// identical, so they stay unqualified.
export type SortableOnStart = (item: HTMLElement) => void;
/**
 * **A `DraggableWarning` means this fault did not decide the outcome** — a
 * landing measurement that could not be trusted, a disposer that refused, a throw
 * a cancel or destruction had already superseded. The operation ends as it would
 * have without it, so do not wait on a warning for a terminal: it may already
 * have arrived, and destruction publishes none. A `DraggableError` means the
 * fault changed the outcome.
 */
export type SortableOnDragError = (
  error: DraggableError | DraggableWarning,
) => void;
/** **One terminal callback, four arms.** */
export type SortableOnEnd = (result: ReorderTransactionResult) => void;
export type ResolveHandle = (item: HTMLElement) => HTMLElement | null;
export type ResolveElement = (item: HTMLElement) => HTMLElement;
/**
 * The collection, pulled on demand.
 *
 * **Every element it returns must be distinct, and that is a definition rather
 * than a restriction.** The pair this API publishes is `{ from, to }`: `from`
 * indexes the collection you returned, `to` indexes the **destination view** —
 * the same collection minus the dragged element — and the two spaces differ by
 * exactly one *only while the dragged element occurs once*. Uniqueness is the
 * condition under which `{ from, to }` has a meaning at all, so a collection
 * naming one element twice has no reorder to describe.
 *
 * **Nothing detects a violation.** The realistic way to reach one is composing
 * this function from overlapping sources — a concatenation, a query that
 * matches a row twice, a virtualized window overlapping its buffer — so it is
 * worth checking at the point where the array is built. A duplicate produces
 * indices in two differently sized spaces, with no error and no cancellation:
 * applying the published pair puts the element somewhere it was not dropped,
 * and a duplicate elsewhere in the list can end a live operation against a
 * republication that changed nothing.
 *
 * Array **identity** is a separate signal and is not this term: returning an
 * equal-but-new array is what tells the library membership may have changed.
 */
export type ItemSource = () => readonly HTMLElement[];

/**
 * The public, stable schema. Every slot is optional in a *fragment*; the
 * required ones are required of the **merged** result.
 */
export type SortableConfig = Readonly<{
  /* required after the merge */
  /**
   * The collection, pulled on demand. **Every element it returns must be
   * distinct** — the condition under which the published `{ from, to }` pair
   * has a meaning. See {@link ItemSource}.
   */
  items: ItemSource;
  onReorder: OnReorder;
  // **Each installer key carries its own type.** A plugin-shaped installer is
  // not assignable here, and the assembler needs no check for one — nor any
  // arbitration, since no other key can produce `insertion`.
  /**
   * `y()` or `xy()`. An **atomic** capability slot: one installer, one whole.
   * The contribution it returns must carry `insertion`.
   */
  axis: AxisInstaller;

  /* optional consumer functions */
  onStart?: SortableOnStart;
  /** Exactly once per started operation, whatever happened to it. */
  onEnd?: SortableOnEnd;
  onError?: SortableOnDragError;
  handle?: ResolveHandle;
  /**
   * The node **faithfully lifted** — what the user sees travel.
   *
   * Defaults to the item, and is expected to resolve to the item or to
   * something inside it. Nothing detects a violation: an unrelated element
   * measures correctly and lifts, but the placeholder then stands in for a
   * footprint the collection never had.
   */
  visual?: ResolveElement;
  /**
   * The **geometry source**: the element whose footprint the placeholder stands
   * in for, and the element every insertion candidate is measured on.
   * `box(item) = visual(item)` by default, which is the common case and costs
   * it nothing.
   *
   * **Separate from `visual` because they answer different questions.** They
   * diverge when the lifted node is nested inside the element that actually
   * holds the space — a row that lifts its inner card, say. Sizing the
   * placeholder from the visual then runs the list too tall for an entire drag,
   * because the visual's own height is not the height its removal freed.
   *
   * **Scope limits, stated positively**: visual order must follow DOM order,
   * rule-placed layouts are unsupported, and in grid `box` must equal
   * `visual`. Nothing detects a violation, so these are documented boundaries
   * rather than guards.
   */
  box?: ResolveElement;
  // The callback itself, not `createPlaceholder` plus a class name.
  /**
   * Changes which element the placeholder is; the behavior always creates one.
   * Must return a **detached** element that is neither the dragged item nor its
   * visual.
   *
   * Nothing detects a violation — the returned element is **adopted**:
   * activation inserts it, every move relocates it, and teardown removes it, so
   * returning an attached node hands the library ownership of something the
   * page owns and teardown then deletes it. A documented boundary, not a guard.
   */
  placeholder?: PlaceholderFactory;

  /* optional capabilities */
  landing?: SortableLandingInstaller;

  /**
   * The displacement feature — `layoutAnimation()`. **One writer**, because two
   * mechanisms writing additive `translate` on the same rows is a collision the
   * key's cardinality makes unrepresentable rather than detectable.
   */
  displacement?: SortableDisplacementInstaller;

  threshold?: number;
}>;

/**
 * The merge iterates the schema, not the fragment's own keys: copying whatever
 * a fragment happens to carry would put an unknown key into the config, where
 * nothing reads it and nothing complains, while walking a fixed list makes a
 * misspelled slot a diagnosable no-op.
 *
 * **Every slot is on it**, which it was not while `plugins` appended.
 */
const LAST_WINS_KEYS = [
  'items',
  'onReorder',
  'axis',
  'onStart',
  'onEnd',
  'onError',
  'handle',
  'visual',
  'box',
  'placeholder',
  'landing',
  'displacement',
  'threshold',
] as const satisfies ReadonlyArray<keyof SortableConfig>;

/**
 * Merge semantics belong to the config slot, not to fragment provenance: the
 * slot's kind decides and a fragment gets no say. Scalars and plain consumer
 * functions last-win, and an atomic capability installer last-wins as one whole
 * slot — which is now every slot there is.
 *
 * Last-wins is safe precisely because installers are invoked after the merge
 * completes. A capability that loses its slot is never constructed — no cache
 * is allocated, no entry appears in `retireHooks`, and there is nothing to
 * retire.
 */
export function mergeFragments(
  config: SortableConfig,
  fragments: ReadonlyArray<Partial<SortableConfig>>,
): SortableConfig {
  // Partial while it is being built, even though the first source is complete:
  // the walk is one loop over one schema, and starting from `{}` keeps the
  // required first argument and the optional fragments on the same code path
  // rather than buying a second one to save an assignment.
  const merged: Partial<Writable<SortableConfig>> = {};

  for (const fragment of [config, ...fragments]) {
    for (const key of LAST_WINS_KEYS) {
      const value = fragment[key];

      if (value !== undefined) {
        // The write is per-key and each key's type is its own; the schema list
        // is what makes it exhaustive, and the cast is confined to this line.
        (merged as Record<string, unknown>)[key] = value;
      }
    }
  }

  // Nothing checks the merged result: `sortable()` takes a complete
  // `SortableConfig` and only the later fragments are `Partial`, so `items`,
  // `onReorder` and `axis` were supplied at a call that could not compile
  // without them.
  //
  // The `undefined` skip above is load-bearing rather than a nicety. A later
  // fragment is a legal `Partial` value and may carry `axis: undefined`;
  // skipping it means a required slot the first argument filled cannot be
  // cleared by a fragment that names it and supplies nothing.
  return merged as SortableConfig;
}
// The consumer-facing controller. Its cancellation and destruction members are
// the kernel's own — the behavior adds the one thing the kernel cannot know
// about: what a collection is.
import type { BehaviorContext } from '../kernel/spec.ts';
import { TAG_COLLECTION } from './runtime.ts';

export type SortableController = Readonly<{
  /**
   * **The committed presentation or data may have changed.** Carries no
   * payload: the collection is a *pull* source, so the library asks `items()`
   * for it rather than being handed one.
   *
   * What this costs depends on what actually changed, and the split is the
   * point: when `items()` returns the **same array identity** the library
   * invalidates geometry and stops, which is what a resize, a zoom or a scroll
   * produces; a **new identity** takes the structural branch — shallow copy,
   * reconcile, geometry invalidation. In-place mutation of the same array is
   * outside the contract.
   *
   * Applied as a queued action, so it lands in FIFO order with everything else
   * the drag is doing — and it is **never discarded**: even a replacement that
   * invalidates the current gap publishes first and cancels afterwards.
   */
  invalidate(): void;
  /**
   * Requests cancellation of the current drag. It is registered only while
   * the drag can still be cancelled, applied in order with everything else
   * the drag is doing, and lapses if the drag is decided first. The outcome
   * arrives as the drag's terminal callback; with no drag it does nothing.
   */
  requestCancel(reason?: unknown): void;
  /**
   * Requests destruction. With no library callback running it is applied
   * before this returns. Called from inside one, the library first finishes
